defmodule Deeper do
  @enforce_keys [:deepest]
  defstruct [:deepest]

  @type t :: %__MODULE__{
          deepest: [[integer()]]
        }
end

defmodule Deep do
  @enforce_keys [:deeper]
  defstruct [:deeper]

  @type t :: %__MODULE__{
          deeper: Deeper.t()
        }
end

defmodule A do
  @enforce_keys [:v]
  defstruct [:v]

  @type t :: %__MODULE__{
          v: integer()
        }
end

defmodule MapClass do
  defstruct [:a, :b, :c, :d, :e, :f, :g, :h]

  @type t :: %__MODULE__{
          a: A.t() | nil,
          b: A.t() | nil,
          c: A.t() | nil,
          d: A.t() | nil,
          e: A.t() | nil,
          f: A.t() | nil,
          g: A.t() | nil,
          h: A.t() | nil
        }
end

defmodule MixedClass do
  @enforce_keys [:nested]
  defstruct [:nested]

  @type t :: %__MODULE__{
          nested: String.t()
        }
end

defmodule TopLevelElement do
  @enforce_keys [:mixed, :maybe, :deep, :map]
  defstruct [:mixed, :maybe, :deep, :map]

  @type t :: %__MODULE__{
          mixed: [[integer()] | boolean() | MixedClass.t() | float() | nil | String.t()],
          maybe: nil | String.t(),
          deep: Deep.t(),
          map: MapClass.t()
        }
end

defmodule Empty do
  defstruct []

  @type t :: %__MODULE__{
        }
end
